answer:
const list = document.querySelector("#list");
document.querySelector("#post").addEventListener("click", () => {
  const url = document.querySelector("#body").value;
  const li = document.createElement("li");
  if (/^https?:\/\//.test(url)) {
    const a = document.createElement("a");
    a.href = url;
    a.textContent = url;
    li.append(a);
  } else {
    li.textContent = url;
  }
  list.append(li);
});
